#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
        const int MOD = 1e9 + 7;
        using P = pair<int, int>;
        priority_queue<P> buy_pq; // max-heap
        priority_queue<P, vector<P>, greater<P>> sell_pq; // min-heap

        for (const auto& ord : orders) {
            int price = ord[0], amount = ord[1], type = ord[2];
            if (type == 0) { // buy
                while (amount > 0 && !sell_pq.empty() && sell_pq.top().first <= price) {
                    auto [s_price, s_amt] = sell_pq.top();
                    sell_pq.pop();
                    int matched = min(amount, s_amt);
                    amount -= matched;
                    if (s_amt > matched) {
                        sell_pq.push({s_price, s_amt - matched});
                    }
                }
                if (amount > 0) buy_pq.push({price, amount});
            } else { // sell
                while (amount > 0 && !buy_pq.empty() && buy_pq.top().first >= price) {
                    auto [b_price, b_amt] = buy_pq.top();
                    buy_pq.pop();
                    int matched = min(amount, b_amt);
                    amount -= matched;
                    if (b_amt > matched) {
                        buy_pq.push({b_price, b_amt - matched});
                    }
                }
                if (amount > 0) sell_pq.push({price, amount});
            }
        }

        long long total = 0;
        while (!buy_pq.empty()) {
            total = (total + buy_pq.top().second) % MOD;
            buy_pq.pop();
        }
        while (!sell_pq.empty()) {
            total = (total + sell_pq.top().second) % MOD;
            sell_pq.pop();
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public int getNumberOfBacklogOrders(int[][] orders) {
        final int MOD = 1_000_000_007;
        PriorityQueue<int[]> buyPq = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        PriorityQueue<int[]> sellPq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));

        for (int[] ord : orders) {
            int price = ord[0], amount = ord[1], type = ord[2];
            if (type == 0) { // buy
                while (amount > 0 && !sellPq.isEmpty() && sellPq.peek()[0] <= price) {
                    int[] sell = sellPq.poll();
                    int matched = Math.min(amount, sell[1]);
                    amount -= matched;
                    sell[1] -= matched;
                    if (sell[1] > 0) {
                        sellPq.offer(sell);
                    }
                }
                if (amount > 0) buyPq.offer(new int[]{price, amount});
            } else { // sell
                while (amount > 0 && !buyPq.isEmpty() && buyPq.peek()[0] >= price) {
                    int[] buy = buyPq.poll();
                    int matched = Math.min(amount, buy[1]);
                    amount -= matched;
                    buy[1] -= matched;
                    if (buy[1] > 0) {
                        buyPq.offer(buy);
                    }
                }
                if (amount > 0) sellPq.offer(new int[]{price, amount});
            }
        }

        long total = 0;
        for (int[] b : buyPq) total = (total + b[1]) % MOD;
        for (int[] s : sellPq) total = (total + s[1]) % MOD;
        return (int)total;
    }
}

