var getNumberOfBacklogOrders = function(orders) {
    const MOD = 1000000007;
    const buyPq = [];
    const sellPq = [];

    const pushMax = (arr, item) => {
        arr.push(item);
        let idx = arr.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (arr[p][0] < arr[idx][0]) {
                [arr[p], arr[idx]] = [arr[idx], arr[p]];
                idx = p;
            } else break;
        }
    };

    const popMax = (arr) => {
        if (arr.length === 0) return null;
        const top = arr[0];
        const last = arr.pop();
        if (arr.length > 0) {
            arr[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, largest = idx;
                if (left < arr.length && arr[left][0] > arr[largest][0]) largest = left;
                if (right < arr.length && arr[right][0] > arr[largest][0]) largest = right;
                if (largest !== idx) {
                    [arr[idx], arr[largest]] = [arr[largest], arr[idx]];
                    idx = largest;
                } else break;
            }
        }
        return top;
    };

    const pushMin = (arr, item) => {
        arr.push(item);
        let idx = arr.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (arr[p][0] > arr[idx][0]) {
                [arr[p], arr[idx]] = [arr[idx], arr[p]];
                idx = p;
            } else break;
        }
    };

    const popMin = (arr) => {
        if (arr.length === 0) return null;
        const top = arr[0];
        const last = arr.pop();
        if (arr.length > 0) {
            arr[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, smallest = idx;
                if (left < arr.length && arr[left][0] < arr[smallest][0]) smallest = left;
                if (right < arr.length && arr[right][0] < arr[smallest][0]) smallest = right;
                if (smallest !== idx) {
                    [arr[idx], arr[smallest]] = [arr[smallest], arr[idx]];
                    idx = smallest;
                } else break;
            }
        }
        return top;
    };

    for (let [price, amount, type] of orders) {
        if (type === 0) {
            while (amount > 0 && sellPq.length > 0 && sellPq[0][0] <= price) {
                const matched = Math.min(amount, sellPq[0][1]);
                amount -= matched;
                sellPq[0][1] -= matched;
                if (sellPq[0][1] === 0) popMin(sellPq);
            }
            if (amount > 0) pushMax(buyPq, [price, amount]);
        } else {
            while (amount > 0 && buyPq.length > 0 && buyPq[0][0] >= price) {
                const matched = Math.min(amount, buyPq[0][1]);
                amount -= matched;
                buyPq[0][1] -= matched;
                if (buyPq[0][1] === 0) popMax(buyPq);
            }
            if (amount > 0) pushMin(sellPq, [price, amount]);
        }
    }

    let total = 0;
    for (const b of buyPq) total = (total + b[1]) % MOD;
    for (const s of sellPq) total = (total + s[1]) % MOD;
    return total;
};
